class Solution(object):
    def maxProduct(self, nums):
        """
        :type nums: List[int]
        :rtype: int
        """
        if not nums:
            return 0
        max_product =  -sys.maxint
        min_positive = 1
        min_negative = - sys.maxint

        partial = 1
        for num in nums:
            partial = partial*num
            if partial>0:
                max_product = max(max_product, partial/min_positive)
                if partial<min_positive:
                    min_positive = partial
            elif partial<0:
                if min_negative==-sys.maxint:
                    max_product = max(max_product, partial)
                else:
                    max_product = max(max_product, partial/min_negative)
                if partial>min_negative:
                    min_negative = partial
            else:
                max_product = max(max_product, 0)
                partial = 1
                min_positive = 1
                min_negative = - sys.maxint
        return max_product

class Solution {
    public int maxProduct(int[] nums) {
       //modified kadanes algoritm
        //edge case
        if(nums.length==0)
            return 0;
        if(nums.length==1)
            return nums[0];
       int maxProduct = 0;
       int currProduct = 1;
       for(int i =0; i<nums.length;i++){
           currProduct = currProduct*nums[i];
           maxProduct = Math.max(currProduct,maxProduct);
           if(currProduct==0)
            currProduct = 1;
       }

       //reverse bcz in case of [3,-1,25] gives wrong answer
      currProduct = 1;
      for(int i= nums.length-1;i>=0;i--){
            currProduct = currProduct*nums[i];
            maxProduct = Math.max(currProduct,maxProduct);
            if(currProduct==0)
                currProduct = 1;
      }
      return maxProduct;

    }
}

class Solution {
    public int maxProduct(int[] nums) {
        int maxProd=nums[0];
        int maxProdUptoI=nums[0];
        int minProdUptoI=nums[0];
        for(int i=1;i<nums.length;i++) {
            if(nums[i]<0){
                int swapVar=maxProdUptoI;
                maxProdUptoI=minProdUptoI;
                minProdUptoI=swapVar;
            }  
            //System.out.println(maxProdUptoI+" "+minProdUptoI);
            maxProdUptoI=Math.max(nums[i],maxProdUptoI*nums[i]);
            minProdUptoI=Math.min(nums[i],minProdUptoI*nums[i]);
            maxProd=Math.max(maxProd,maxProdUptoI);
        }
        return maxProd;
    }    
}
